{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-bxn6Vc/src/parse.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph text format into a map of task costs and a map of
 * dependency lists, both keyed by task name. Throws a `CliError` on any
 * malformed directive, invalid name, invalid cost, duplicate declaration,
 * unknown directive or unknown task reference, per the written spec.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map() // name -> cost
  const depLines = [] // { name, deps: [...] }, in input order

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, costWord] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNumber}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costWord)) {
        throw new CliError(`line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNumber}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costWord, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      const [, name, ...deps] = words
      depLines.push({ name, deps })
    } else {
      throw new CliError(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  // Every name a dep line uses must be a declared task. Report the first
  // such name in input order, scanning the dependent name before its
  // dependencies on each line.
  for (const { name, deps } of depLines) {
    for (const used of [name, ...deps]) {
      if (!tasks.has(used)) {
        throw new CliError(`unknown task ${used}`, 2)
      }
    }
  }

  const depsMap = new Map()
  for (const name of tasks.keys()) depsMap.set(name, new Set())
  for (const { name, deps } of depLines) {
    const set = depsMap.get(name)
    for (const dep of deps) set.add(dep)
  }

  const dependencies = new Map()
  for (const [name, set] of depsMap) dependencies.set(name, [...set])

  return { tasks, dependencies }
}
"}

