{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-bxn6Vc/src/cycle.js","content":"const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

/**
 * Finds the first cycle a depth-first search encounters, starting from each
 * task in ascending name order and walking each task's dependencies in
 * ascending name order. Returns the cycle as an array of names running from
 * the re-entered task through the search stack and back to it, or `null`
 * when the graph is acyclic.
 */
export function findCycle(tasks, dependencies) {
  const names = [...tasks.keys()].sort(cmp)
  const state = new Map(names.map((n) => [n, 'white']))
  const stack = []

  function visit(name) {
    state.set(name, 'gray')
    stack.push(name)
    const deps = [...dependencies.get(name)].sort(cmp)
    for (const dep of deps) {
      const depState = state.get(dep)
      if (depState === 'gray') {
        const start = stack.indexOf(dep)
        return [...stack.slice(start), dep]
      } else if (depState === 'white') {
        const found = visit(dep)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 'black')
    return null
  }

  for (const name of names) {
    if (state.get(name) === 'white') {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}
"}

