{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-bxn6Vc/src/schedule.js","content":"const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

/**
 * Computes, for every task, the start time, finish time and wave depth
 * described by the spec: start is the greatest finish among its
 * dependencies (0 when it has none), finish is start plus cost, and depth
 * is one more than the greatest depth among its dependencies (0 when it has
 * none). Assumes the graph is acyclic.
 */
export function computeTimings(tasks, dependencies) {
  const result = new Map()

  function resolve(name) {
    if (result.has(name)) return result.get(name)
    const deps = dependencies.get(name)
    let start = 0
    let depth = 0
    for (const dep of deps) {
      const depInfo = resolve(dep)
      if (depInfo.finish > start) start = depInfo.finish
      if (depInfo.depth + 1 > depth) depth = depInfo.depth + 1
    }
    const finish = start + tasks.get(name)
    const info = { start, finish, depth }
    result.set(name, info)
    return info
  }

  for (const name of tasks.keys()) resolve(name)
  return result
}

/**
 * Computes, for every task, the cost of the longest chain that begins at it
 * and runs forward through its dependents down to a task nothing depends
 * on, counting each task's own cost along the way. Assumes the graph is
 * acyclic.
 */
export function computePriorities(tasks, dependencies) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of dependencies) {
