{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-bxn6Vc/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { findCycle } from './cycle.js'
import { computeTimings, packSchedule } from './schedule.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw new CliError('workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE)
}

function renderWaves(tasks, timings) {
  const names = [...tasks.keys()].sort(cmp)
  let maxDepth = -1
  for (const info of timings.values()) if (info.depth > maxDepth) maxDepth = info.depth

  const waves = []
  for (let d = 0; d <= maxDepth; d++) waves.push([])
  for (const name of names) waves[timings.get(name).depth].push(name)

  const lines = waves.map((wave, k) => `wave ${k}: ${wave.join(' ')}`)
  const total = [...timings.values()].reduce((max, info) => Math.max(max, info.finish), 0)
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function renderExplain(tasks, timings) {
  const names = [...tasks.keys()].sort(cmp)
  const lines = names.map((name) => {
    const { start, finish, depth } = timings.get(name)
    return `${name} start=${start} finish=${finish} depth=${depth}`
  })
  const total = [...timings.values()].reduce((max, info) => Math.max(max, info.finish), 0)
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function renderPack(tasks, dependencies, workers) {
  const { workers: workerLog, makespan } = packSchedule(tasks, dependencies, workers)
  const lines = workerLog.map((runs, i) => {
    const entries = runs.map((r) => ` ${r.name}@${r.start}-${r.finish}`).join('')
    return `worker ${i}:${entries}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = readFileSync(0, 'utf8')
  const { tasks, dependencies } = parseGraph(input)

  const cycle = findCycle(tasks, dependencies)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
  }

  let output
  if (args.mode === 'waves') {
    output = renderWaves(tasks, computeTimings(tasks, dependencies))
  } else if (args.mode === 'explain') {
    output = renderExplain(tasks, computeTimings(tasks, dependencies))
  } else {
    output = renderPack(tasks, dependencies, args.workers)
  }
  process.stdout.write(output)
}

try {
  main()
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(err.exitCode)
  }
  throw err
}
"}

